assert_equals "tickets exposes the required columns and nullability" "SELECT GROUP_CONCAT(CONCAT(COLUMN_NAME,':',COLUMN_TYPE,':',IS_NULLABLE) ORDER BY COLUMN_NAME SEPARATOR ';') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tickets'" "agent_id:int:YES;id:int:NO"
assert_equals "draft_lines exposes the required columns and nullability" "SELECT GROUP_CONCAT(CONCAT(COLUMN_NAME,':',COLUMN_TYPE,':',IS_NULLABLE) ORDER BY COLUMN_NAME SEPARATOR ';') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='draft_lines'" "draft_id:int:NO;id:int:NO"
assert_equals "invoices exposes the required columns and nullability" "SELECT GROUP_CONCAT(CONCAT(COLUMN_NAME,':',COLUMN_TYPE,':',IS_NULLABLE) ORDER BY COLUMN_NAME SEPARATOR ';') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='invoices'" "customer_id:int:NO;id:int:NO"
# Test descriptions are in English. SQL assertions use the isolated test database.
assert_accepts "Related records can be created" "INSERT INTO tickets VALUES(1,1); INSERT INTO draft_lines VALUES(1,1); INSERT INTO invoices VALUES(1,1)"
assert_accepts "Agent key changes are propagated" "UPDATE agents SET id=2 WHERE id=1"
assert_equals "The ticket follows the agent key" "SELECT agent_id FROM tickets WHERE id=1" "2"
assert_accepts "An agent can be removed without deleting the ticket" "DELETE FROM agents WHERE id=2"
assert_equals "An unassigned ticket is retained" "SELECT agent_id IS NULL FROM tickets WHERE id=1" "1"
assert_accepts "Draft key changes are propagated" "UPDATE drafts SET id=2 WHERE id=1"
assert_equals "The line follows the draft key" "SELECT draft_id FROM draft_lines WHERE id=1" "2"
assert_accepts "A draft and its lines can be deleted" "DELETE FROM drafts WHERE id=2"
assert_equals "Draft lines are removed" "SELECT COUNT(*) FROM draft_lines" "0"
assert_rejects "An invoiced customer cannot be deleted" "1451" "DELETE FROM customers WHERE id=1"
assert_rejects "An invoiced customer key cannot change" "1451" "UPDATE customers SET id=2 WHERE id=1"
assert_rejects "Unknown agents cannot be assigned" "1452" "INSERT INTO tickets VALUES(2,99)"
